#include "embedded_multiboot.h"
#include <stdio.h>
#include <string.h>

static const char catalog[] = "FM1CAT|1\nID|LABEL|VERSION|FILE|SIZE|SHA256|COMPAT\nONE|ONE DEMO|1.0|ONE.BIN|3|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|UNVERIFIED\nTWO|TWO & DEMO|2.0|TWO.FWS|3|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|UNVERIFIED\nTHREE|THREE DEMO|3.0|THREE.BIN|3|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|UNVERIFIED\n";
static FILE *svg, *trace;
static enum mb_io_result read_memory(void *context,const char *path,uint32_t offset,uint8_t *out,uint32_t cap,uint32_t *got)
{ (void)context; if(!strcmp(path,"FM1/INDEX.CSV")){if(offset>=sizeof catalog-1)return MB_IO_EOF;*got=(uint32_t)(sizeof catalog-1-offset);if(*got>cap)*got=cap;memcpy(out,catalog+offset,*got);return MB_IO_OK;} if(!strncmp(path,"FM1/FW/",7)){const char data[]="abc";if(offset>=3)return MB_IO_EOF;*got=3-offset;if(*got>cap)*got=cap;memcpy(out,data+offset,*got);return MB_IO_OK;} return MB_IO_MISSING; }
static void xml(const char *s){for(;*s;s++){switch(*s){case '&':fputs("&amp;",svg);break;case '<':fputs("&lt;",svg);break;case '>':fputs("&gt;",svg);break;case '"':fputs("&quot;",svg);break;case '\'':fputs("&apos;",svg);break;default:fputc(*s,svg);}}}
static void begin(void *context){(void)context;fprintf(svg,"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"240\" height=\"240\" viewBox=\"0 0 240 240\"><rect width=\"240\" height=\"240\" fill=\"#08131a\"/><style>text{font-family:monospace;fill:#65e8cd}</style>");}
static void card(void *context,const struct mb_entry *e,int side,int focus){(void)context;int x=focus?70:(side<0?12:158),w=focus?100:70;fprintf(svg,"<rect x=\"%d\" y=\"45\" width=\"%d\" height=\"105\" rx=\"8\" fill=\"%s\" stroke=\"#65e8cd\"/><text x=\"%d\" y=\"100\" text-anchor=\"middle\">",x,w,focus?"#183841":"#10242a",x+w/2);xml(e->label);fprintf(svg,"</text><text x=\"%d\" y=\"120\" text-anchor=\"middle\">",x+w/2);xml(e->version);fputs("</text>",svg);}
static void text(void *context,const char *s){(void)context;fputs("<text x=\"120\" y=\"205\" text-anchor=\"middle\">",svg);xml(s);fputs(" · PLAY INSPECT ONLY</text>",svg);}
static void end(void *context){(void)context;fputs("</svg>\n",svg);}
int main(void){struct mb_core c;svg=fopen("build/embedded-coverflow-demo.svg","w");trace=fopen("build/embedded-e2e-trace.txt","w");if(!svg||!trace)return 2;mb_init(&c,(struct mb_storage){0,read_memory},(struct mb_renderer){0,begin,card,text,end});fprintf(trace,"BOOT\n");if(mb_load_catalog(&c)!=MB_IO_OK)return 3;fprintf(trace,"CATALOG %s %u\n",mb_state_name(c.state),c.catalog.count);mb_event(&c,MB_EVENT_NEXT);fprintf(trace,"SELECT %s %s\n",mb_state_name(c.state),mb_selected(&c)->id);mb_event(&c,MB_EVENT_PLAY);fprintf(trace,"INSPECT %s\n",mb_state_name(c.state));mb_event(&c,MB_EVENT_REC);fprintf(trace,"BACK %s\n",mb_state_name(c.state));if(mb_verify_selected(&c)!=MB_IO_OK)return 4;fprintf(trace,"VERIFY %s integrity=%u\n",mb_state_name(c.state),mb_selected(&c)->integrity_verified);mb_render(&c);fprintf(trace,"RENDER 240x240\n");fclose(svg);fclose(trace);puts("embedded Cover Flow demo: end-to-end trace and escaped SVG: OK");return 0;}
